INSERT INTO decisions (decision_id, category, delegation, delegation_rationale, summary, outcome, rationale, decision_date, decided_by, model_routing, effort_level, status, review_status, supersedes, predecessors, decision_artifacts, alternatives_considered, notes, created_at, created_by_session, updated_at, updated_by_session) VALUES ('D-0167', 'D-SCHEMA', 'DG-NON', 'Owner ruling. The pipeline shape, the project vocabulary and the research methodology are judgements about the book, which governance/decision-protocol.md places in the DG-NON class and CLAUDE.md rule 0 makes non-delegable.', 'The pipeline is SEVEN stages and `base` is the first: Base, Research, Evidence, Judgment, Synthesis, Specification, Render.', 'ADOPTED by owner ruling 2026-08-27. Ends the "substrate is not a stage" convention, which was agent-coined on 2026-08-24 and used as canon for three days. Supersedes the five-stage list (2026-08-25) and the six-stage list (2026-08-27 am).', 'The owner ruled base a stage because "it supplies the base information upon which research can perform its task, and it doesn''t belong under research because none of it IS research. it''s the first layer of information." Re-deriving both live figures under base-as-stage-1, using the R1 audit assignment: foreign keys go from 21/59 to 49/31 cross-stage/within, reclassifying 28 keys and taking cross-stage from 26% to 61% of the schema''s 80; cross-stage views go from 9 to 10 of 18. The long-quoted "43/37 on eight columns" matches neither convention and is void. Because a cross-stage view IS the pointer, the protected set grows, and the view that joins it is v_coverage_priority (base+research, 7,208 rows) -- the matrix view, which two successive plans proposed deleting.', '2026-08-27 13:52', 'jordanelias', 'human/none/none', '0', 'ACTIVE', 'NA', '[]', '[]', '["decisions/DR-2026-08-27-seven-stage-spine-base-is-first.md", "references/project-standards.md (entries dated 2026-08-27)", "references/owner-notes/2026-08-27-architecture-note.md", "scratchpad/session_2026-08-27-hook-audit/audits/R1-stage-assignment.md"]', '["Keep substrate outside the stage set (the retired convention) -- rejected: the owner ruled base supplies what research consumes, so it is a producing layer, and \"substrate\" was never owner vocabulary.", "Fold base under research -- rejected by the owner in terms: none of base IS research."]', 'Companion ruling recorded the same contact: a table is never a stage ("Slugs isn''t a stage as that word doesn''t actually make sense for it"). Neither governance/pipeline-contract.yaml nor tools/pipeline_completeness.py has been updated; both still enforce five stages. Propagation owed.', '2026-08-27 13:52', 'session_2026-08-27-rename-execution', '2026-08-27 13:52', 'session_2026-08-27-rename-execution');
INSERT INTO decisions (decision_id, category, delegation, delegation_rationale, summary, outcome, rationale, decision_date, decided_by, model_routing, effort_level, status, review_status, supersedes, predecessors, decision_artifacts, alternatives_considered, notes, created_at, created_by_session, updated_at, updated_by_session) VALUES ('D-0168', 'D-SCHEMA', 'DG-NON', 'Owner ruling. The pipeline shape, the project vocabulary and the research methodology are judgements about the book, which governance/decision-protocol.md places in the DG-NON class and CLAUDE.md rule 0 makes non-delegable.', 'The evidence item is the SOURCE; the judgment item is the extracted, tiered, categorised value. Evidence to judgment is 1:N.', 'ADOPTED by owner ruling 2026-08-27, adopting item #2 of the architecture note. source_value_extractions re-assigns from evidence to judgment.', 'The owner: "one evidence source may provide many rows of judgment (eg a code document like Canada''s NBC 3.8)", and judgment "determines category of judgment item, derives value/process/figure/goal for it". So the value is derived at judgment, not evidence, and the evidence row is the source record. This moots three findings the adversarial passes had raised as blockers: A3-F3 (the lead key put a per-source fact on a per-extraction row), A3-F18 (the population-match grain conflict), and my own rejection of the 25-grades-over-10-sources measurement as the wrong edge -- it was always the right edge. judgment_items is not a new table needing a designed column set; it inherits the extraction table.', '2026-08-27 13:52', 'jordanelias', 'human/none/none', '0', 'ACTIVE', 'NA', '[]', '[]', '["decisions/DR-2026-08-27-evidence-is-the-source-judgment-is-the-extraction.md", "references/project-standards.md (entries dated 2026-08-27)", "references/owner-notes/2026-08-27-architecture-note.md"]', '["1:1 with UNIQUE(evidence_item_id) -- rejected by the owner''s own worked example, a code document yielding many clause-level judgments.", "Keep extraction in evidence collection -- rejected: it puts the tier verdict and the derived value in a stage the owner defines as a cursory scan."]', 'Owed and not free: the tier verdict is a judgment output but `tier` is a column on evidence_sources. Measured 2026-08-27: 40 Python files name evidence_sources, 78 Python lines name a tier field, 26 skills teach tier. Writer-retire, reader-retire, NULL forward. Queued, not done.', '2026-08-27 13:52', 'session_2026-08-27-rename-execution', '2026-08-27 13:52', 'session_2026-08-27-rename-execution');
INSERT INTO decisions (decision_id, category, delegation, delegation_rationale, summary, outcome, rationale, decision_date, decided_by, model_routing, effort_level, status, review_status, supersedes, predecessors, decision_artifacts, alternatives_considered, notes, created_at, created_by_session, updated_at, updated_by_session) VALUES ('D-0169', 'D-SCHEMA', 'DG-NON', 'Owner ruling. The pipeline shape, the project vocabulary and the research methodology are judgements about the book, which governance/decision-protocol.md places in the DG-NON class and CLAUDE.md rule 0 makes non-delegable.', 'The naming grammar: underscore separator, `base_` prefix, parallel `base_taxonomy_*` names, the `icf_*` family, and singular stage ids.', 'ADOPTED by owner selections 2026-08-27. Supersedes the dotted namespace of the architecture note, the three-character stage_id[:3] prefix scheme, and the §R8 `demand_*` replacement family.', 'Underscore because SQLite has no schemas: a dot in an identifier collides with schema.table syntax and would need quoting at every use site forever. Full-word prefixes also retire the collision hazard found against three-character prefixes. The taxonomies keep parallel names because the owner ruled "we have multiple taxonomies. respect that", which is also a bar on folding. The ICF family takes icf_* throughout AND access_need_icf (43 rows) is renamed access_need_icf_codes, because access_need_icf maps needs to ICF e-codes while the axes table holds b/d codes -- leaving them one letter apart would recreate the `items` ambiguity deliberately. The stage id is singular against the owner''s own plural wording, so the prefix matches the other six and the hand-off reads specification_items.', '2026-08-27 13:52', 'jordanelias', 'human/none/none', '0', 'ACTIVE', 'NA', '[]', '[]', '["decisions/DR-2026-08-27-naming-grammar-underscore-icf-family-singular-stage-ids.md", "references/project-standards.md (entries dated 2026-08-27)"]', '["Keep the \u00a7R8 demand_* family -- rejected: it was derived from `icf_demands`, a noun the owner has replaced, so the derivation no longer holds.", "icf_* without renaming access_need_icf -- rejected by the owner as inheriting a known collision.", "Plural stage id `specifications_` as the owner first wrote it -- rejected for prefix consistency; the plural remains the recorded wording of the spine ruling."]', '§R8''s seven RETIRED tokens (axes, axis_code, item_axis_links, population_axis_map, access_need_axis_map, serves_axes, attaches_axes) are unaffected -- they name what is retired, not what replaces it.', '2026-08-27 13:52', 'session_2026-08-27-rename-execution', '2026-08-27 13:52', 'session_2026-08-27-rename-execution');
INSERT INTO decisions (decision_id, category, delegation, delegation_rationale, summary, outcome, rationale, decision_date, decided_by, model_routing, effort_level, status, review_status, supersedes, predecessors, decision_artifacts, alternatives_considered, notes, created_at, created_by_session, updated_at, updated_by_session) VALUES ('D-0170', 'D-DOCT', 'DG-NON', 'Owner ruling. The pipeline shape, the project vocabulary and the research methodology are judgements about the book, which governance/decision-protocol.md places in the DG-NON class and CLAUDE.md rule 0 makes non-delegable.', 'The four disability taxonomies are user-selectable browsing lenses, and the medical model is included.', 'ADOPTED by owner ruling 2026-08-27. base_taxonomy_medical (new), base_taxonomy_identity (populations), base_taxonomy_icf (axes), base_taxonomy_needs (access_needs).', 'The owner: "yes we include the medical model too. we give our users the choice of what model they want to use to browse the site." This resolves the DG-NON objection rather than overriding it: a medical-model taxonomy in a CRPD-aligned project reads as a doctrinal reversal only if it is the project''s own frame, and it is not -- it is user agency over how a reader''s experience is described, which is the social model''s commitment applied to the interface. A reader who thinks in diagnoses is not forced to translate into ICF codes; a reader who refuses the medical frame never sees it. Consistent with CRPD Art 4.3. Structural consequence: lens-switching runs through the crossing maps, so a medical taxonomy needs the same crossings into the other three or the lens cannot switch. It is a schema change, not a vocabulary addition.', '2026-08-27 13:52', 'jordanelias', 'human/none/none', '0', 'ACTIVE', 'NA', '[]', '[]', '["decisions/DR-2026-08-27-four-taxonomies-are-browsing-lenses.md", "references/project-standards.md (entries dated 2026-08-27)", "references/owner-notes/2026-08-27-architecture-note.md"]', '["Omit the medical model as inconsistent with the social-model posture -- rejected by the owner; it mistakes offering a lens for adopting a frame.", "Fold the taxonomies into one -- rejected: \"we have multiple taxonomies. respect that\", and the 2026-08-25 anti-fold ruling measured that axes anchors ICF b/d while access_needs anchors e."]', NULL, '2026-08-27 13:52', 'session_2026-08-27-rename-execution', '2026-08-27 13:52', 'session_2026-08-27-rename-execution');
INSERT INTO decisions (decision_id, category, delegation, delegation_rationale, summary, outcome, rationale, decision_date, decided_by, model_routing, effort_level, status, review_status, supersedes, predecessors, decision_artifacts, alternatives_considered, notes, created_at, created_by_session, updated_at, updated_by_session) VALUES ('D-0171', 'D-SCHEMA', 'DG-NON', 'Owner ruling. The pipeline shape, the project vocabulary and the research methodology are judgements about the book, which governance/decision-protocol.md places in the DG-NON class and CLAUDE.md rule 0 makes non-delegable.', 'base_building holds three levels -- building type, room type, construction element -- and `items` is none of them.', 'ADOPTED by owner ruling 2026-08-27. The 2026-08-26 ruling that `items` is the Part-4 render rollup therefore stands unamended.', 'The owner: "Building types (eg residential, commercial), room types (eg kitchen, entry, bathroom), construction elements (eg door, door handle, window, floor) are what I wanted for that table." Measured: only the middle level exists (rooms, 17 rows -- R-KIT, R-ENT, R-BA); building types and construction elements have no table. items (93) holds design provisions ABOUT elements, e.g. A-03 "Acoustic Door (STC >=35) at All Sensitive Space Boundaries". This explains a defect already on the record: 42 of 93 item names carry a determination in the label because items conflates the element (door), the parameter (STC) and the determination (>=35), with no element table and no parameter registry to hold them apart. The proposed vocabulary check treats the symptom; the three-level split removes the cause.', '2026-08-27 13:52', 'jordanelias', 'human/none/none', '0', 'ACTIVE', 'NA', '[]', '[]', '["decisions/DR-2026-08-27-base-building-three-levels-items-is-not-one.md", "references/project-standards.md (entries dated 2026-08-27)", "scratchpad/session_2026-08-27-rename-execution/AGONIST-ANTAGONIST.md"]', '["Rename items into base_building -- rejected on measurement: items holds provisions, not elements.", "Three separate tables -- weighed against one self-referential table, because the owner said \"that table\" and separately ruled parent columns; a parent across three tables is polymorphic, which SQLite cannot key. Shape recorded as open in the agonist-antagonist pass."]', 'items.category holds 10 distinct bare letters A-K with no category-name table anywhere -- the same collapse a second time.', '2026-08-27 13:52', 'session_2026-08-27-rename-execution', '2026-08-27 13:52', 'session_2026-08-27-rename-execution');
INSERT INTO decisions (decision_id, category, delegation, delegation_rationale, summary, outcome, rationale, decision_date, decided_by, model_routing, effort_level, status, review_status, supersedes, predecessors, decision_artifacts, alternatives_considered, notes, created_at, created_by_session, updated_at, updated_by_session) VALUES ('D-0172', 'D-SCHEMA', 'DG-NON', 'Owner ruling. The pipeline shape, the project vocabulary and the research methodology are judgements about the book, which governance/decision-protocol.md places in the DG-NON class and CLAUDE.md rule 0 makes non-delegable.', 'base_sources is a registry of research TARGETS -- prompts for where to look. It is neither evidence nor research.', 'ADOPTED by owner ruling 2026-08-27, correcting an agent finding that had called it a duplication defect.', 'The owner: "academic publishing institutions, research journals, university publications, books and articles, etc are all sources for finding evidence sources. so too are countries, codes and standards, professional organizations, clinical bodies, and advocacy groups. none of these are evidence, and none of these are research. they are all prompts for research to target such that they can find evidence." Both bullets of the architecture note are one coherent member and neither is the corpus; the agent error came from reading "sources" as this project''s evidence_sources. It is a third input to the research matrix alongside the clue store. Measured: no target registry exists, and the nearest thing is search_executions.engine -- free text, no vocabulary, no table, no CHECK -- so target coverage is not a derivable fact and a body nobody thought to search is invisible to every gate.', '2026-08-27 13:52', 'jordanelias', 'human/none/none', '0', 'ACTIVE', 'NA', '[]', '[]', '["decisions/DR-2026-08-27-base-sources-is-a-target-registry.md", "references/project-standards.md (entries dated 2026-08-27)", "references/owner-notes/2026-08-27-architecture-note.md"]', '["Treat the two bullets as a source-type taxonomy plus the academic corpus -- refuted by the owner; neither is the corpus."]', 'Nomenclature hazard flagged at ratification: "sources" would then do two jobs -- base_sources is where to look, evidence_sources is what we found. That is the class the owner retired `items` for. Resolve the name before the table exists.', '2026-08-27 13:52', 'session_2026-08-27-rename-execution', '2026-08-27 13:52', 'session_2026-08-27-rename-execution');
INSERT INTO decisions (decision_id, category, delegation, delegation_rationale, summary, outcome, rationale, decision_date, decided_by, model_routing, effort_level, status, review_status, supersedes, predecessors, decision_artifacts, alternatives_considered, notes, created_at, created_by_session, updated_at, updated_by_session) VALUES ('D-0173', 'D-METH', 'DG-NON', 'Owner ruling. The pipeline shape, the project vocabulary and the research methodology are judgements about the book, which governance/decision-protocol.md places in the DG-NON class and CLAUDE.md rule 0 makes non-delegable.', 'The concept vocabulary is harvested at evidence and adjudicated at judgment. DR-2026-08-24 §2.4 deferral to synthesis is OVERRULED.', 'ADOPTED by owner ruling 2026-08-27: "overrule Aug 24 DR. we go evidence>judgment>synthesis."', 'The owner posed the aporia: "we do not want to presuppose categories/concepts/approaches/elements/techniques/practices by defining them all at the start of the project. however, we also can''t perform our research properly if we don''t presuppose all of those." It is a false dilemma. The vocabulary need not be stipulated or absent; it can be observed but not yet adjudicated. Recording that a source uses a phrase is a fact about the document, not a claim that the phrase names one of our categories -- the same epistemic act as recording its DOI. Judgment then adjudicates with the source in hand, and the vocabulary is grown with warrant. The seed problem is answered by ratified doctrine rather than a new decision: pipeline-map.yaml:78 (2026-08-21) establishes that these are layers a walk re-enters. Measured: most of the mechanism exists -- evidence_sources carries 30 APA-shaped columns including _en variants, and terms (88) plus term_aliases (2,382) plus term_item_links (147) are the canonical layer. Missing is the harvest; nothing holds terms as they appear in a source, and search_executions.terms_used is the opposite direction.', '2026-08-27 13:52', 'jordanelias', 'human/none/none', '0', 'ACTIVE', 'NA', '[]', '[]', '["decisions/DR-2026-08-27-concept-vocabulary-harvested-at-evidence-adjudicated-at-judgment.md", "references/project-standards.md (entries dated 2026-08-27)", "references/owner-notes/2026-08-27-architecture-note.md"]', '["Keep the \u00a72.4 deferral to synthesis -- overruled by the owner; judgment holds the source and synthesis does not, so judgment serves the DR''s own purpose better.", "Stipulate the vocabulary up front -- rejected by the owner as the presupposition the aporia warns against."]', 'Scoped to §2.4. §2.1 (rule 5, "point, do not copy") is untouched and remains operative; the R2 audit found this scoping "defensible and compelled, not protective narrowing", by reductio -- the whole-DR reading would strike §R8, which the owner re-affirmed the same day. Sweep owed: CLAUDE.md §6 states "applicability is an OUTPUT of synthesis" and "zero item_population_links is the correct pre-synthesis state", both superseded; D-0165 moves upstream; research_batch_dod R4 measures the wrong stage.', '2026-08-27 13:52', 'session_2026-08-27-rename-execution', '2026-08-27 13:52', 'session_2026-08-27-rename-execution');
INSERT INTO decisions (decision_id, category, delegation, delegation_rationale, summary, outcome, rationale, decision_date, decided_by, model_routing, effort_level, status, review_status, supersedes, predecessors, decision_artifacts, alternatives_considered, notes, created_at, created_by_session, updated_at, updated_by_session) VALUES ('D-0174', 'D-METH', 'DG-NON', 'Owner ruling. The pipeline shape, the project vocabulary and the research methodology are judgements about the book, which governance/decision-protocol.md places in the DG-NON class and CLAUDE.md rule 0 makes non-delegable.', 'Relevance is an adjudication made at evidence collection, against a topic; applicability remains a synthesis judgement.', 'ADOPTED by owner ruling 2026-08-27: "evidence states relevant items, and relevancy is something that must be adjudicated against a topic/category/concept."', 'Relevance is not a property a document carries but a relation, so evidence collection judges -- it simply judges a different question from judgment. This refutes an agent finding that the evidence stage was a "pure log" and that R1 (phase before-admitting) therefore conflicted with it; there is no conflict. The distinction from applicability must be protected: DR-2026-08-24 §2.4 defers applicability and says nothing about relevance, and cannot, since relevance must be settled at collection or nothing can be admitted. Conflating them breaks both ways. Measured defect: source_slug_links.relevance_note exists and is populated in 0 of 10 rows, and search_admissions records no grounds at all -- the adjudication is made every time and recorded never. Under the harvest ruling (D-0173) the grounds become derivable rather than hand-written.', '2026-08-27 13:52', 'jordanelias', 'human/none/none', '0', 'ACTIVE', 'NA', '[]', '[]', '["decisions/DR-2026-08-27-relevance-is-adjudicated-at-collection.md", "references/project-standards.md (entries dated 2026-08-27)"]', '["Treat evidence collection as a pure log with all judgement deferred -- refuted by the owner: \"relevant\" is itself an adjudication."]', 'Granularity gap measured: the owner names topic/category/concept, but slugs is flat -- no parent, category, group or level column, 106 leaves. A source relevant at the category level can only be copied across every leaf (rule 5) or lost. The owner has ruled parent columns are needed.', '2026-08-27 13:52', 'session_2026-08-27-rename-execution', '2026-08-27 13:52', 'session_2026-08-27-rename-execution');